#!/usr/bin/env python3
"""Deterministic project extraction with page evidence; amounts remain source-labelled disclosures."""
import json,re,subprocess
from decimal import Decimal
import pandas as pd
from acquire import ROOT,DATA,save_json
from normalize import digest,tags

def commons():
 records=[];profiles=[];manifest=[json.loads(x) for x in (ROOT/'validation/http_manifest.jsonl').read_text().splitlines()]
 for p in sorted((DATA/'raw/commons').glob('*.pdf')):
  m=next(x for x in manifest if x.get('relative_path')==str(p.relative_to(DATA)));text=subprocess.run(['pdftotext','-layout',str(p),'-'],capture_output=True,text=True).stdout;rawpages=text.split('\f');text=re.sub(r'Distribution Statement A: Approved for public release\. Distribution is unlimited\.','',text).replace('\f','\n');paras=re.split(r'\n\s*\n',text);current=None;count=0
  for para in paras:
   if 'Lead:' in para and '$' in para:
    # Amount/lead labels appear in project headers; the indented narrative follows.
    head=re.split(r'\n {2,}',para,maxsplit=1)[0];head=re.sub(r'^.*Projects\s*\n','',head);flat=' '.join(head.split());match=re.search(r'\$\s*([\d.]+)\s*([Mk]?)\s*,?\s*(.*?)Lead:\s*(.*)',flat)
    if not match:continue
    title=flat[:match.start()].rstrip(' -');lead=match[4].rstrip('- ');page=next((i+1 for i,t in enumerate(rawpages) if title[:30] in ' '.join(t.split())),None)
    current={'document_id':'commons_project:'+digest(m['sha256']+'|'+title),'source':'commons','title':title,'lead_text':lead,'source_url':m['url']+(f'#page={page}' if page else ''),'source_snapshot_sha256':m['sha256'],'retrieved_at':m['retrieved_at'],'raw_file':p.name,'raw_locator':str(p.relative_to(DATA))+f'#page={page}','raw_page':page,'disclosed_project_amount_raw':match[0].split('Lead:')[0].strip(),'unit_in_source':match[2] or 'UNSPECIFIED','amount_usd':str(Decimal(match[1])*({'M':1_000_000,'k':1000}[match[2]])) if match[2] else None,'amount_label_in_source':match[0].split('Lead:')[0]+'Lead:','money_semantics':'Disclosed project amount in technology-area sheet; financial time basis/obligation status unspecified. Not an action obligation, outlay, ceiling or total program sum without corroboration. Cross-area project mentions can overlap.','text':para.strip(),'eligibility':'security_capability_candidate;amount_basis_review_required'};records.append(current);count+=1
   elif current:current['text']+='\n\n'+para.strip()
  profiles.append({'file':p.name,'parsed_project_headers':count,'currency_M_mentions':len(re.findall(r'\$\s*[\d.]+\s*M',text)),'lead_mentions':text.count('Lead:')})
 for r in records:r['capability_tags']=json.dumps(tags(r['title']+' '+r['text']));r['evidence_excerpt']=r['text'][:900]
 d=pd.DataFrame(records);d.to_parquet(DATA/'normalized/commons_projects.parquet',index=False);d.to_json(DATA/'normalized/commons_projects.jsonl.gz',orient='records',lines=True,compression='gzip');d.drop(columns=['text']).head(10).to_csv(ROOT/'samples/commons_projects.csv',index=False);save_json(ROOT/'validation/commons_project_profile.json',{'files':profiles,'rows':len(d),'missing_pages':int(d.raw_page.isna().sum()),'duplicate_titles':int(d.title.duplicated().sum()),'unspecified_amount_units':int((d.unit_in_source=='UNSPECIFIED').sum()),'warning':'Extracted project headers are not a verified census of unique investments. Preserve named co-development/cross-project relationships as hypotheses; amounts must not be combined with transactions.'});print('Commons projects',len(d),flush=True)
def apfit():
 p=DATA/'raw/apfit/APFIT_20230321.pdf';m=next(json.loads(x) for x in (ROOT/'validation/http_manifest.jsonl').read_text().splitlines() if json.loads(x).get('relative_path')==str(p.relative_to(DATA)));text=subprocess.run(['pdftotext','-layout',str(p),'-'],capture_output=True,text=True).stdout;pages=text.split('\f');start=text.find('1. Advanced Sensor Package Procurement');end=text.find('4. Lessons Learned',start);body=text[start:end if end!=-1 else len(text)];matches=list(re.finditer(r'(?m)^\s*(\d{1,2})\.\s+([A-Z][^\n]+)\n\s+a\.\s+Project Description:',body));records=[]
 for i,match in enumerate(matches):
  block=body[match.start():matches[i+1].start() if i+1<len(matches) else len(body)];company=re.search(r'b\.\s+Company:\s*(.*?)(?=\n\s+c\.)',block,re.S);dt=re.search(r'c\.\s+Contract Award Date:\s*(.*?)(?=\n\s+d\.)',block,re.S);title=match[2].strip();page=next((j+1 for j,t in enumerate(pages) if title[:25] in t),None)
  records.append({'document_id':'apfit_FY2022:'+match[1],'source':'apfit','raw_locator':str(p.relative_to(DATA))+f'#page={page}','source_snapshot_sha256':m['sha256'],'retrieved_at':m['retrieved_at'],'capability_tags':json.dumps(tags(title+' '+block)),'source_url':'https://calvert.house.gov/sites/evo-subsites/calvert.house.gov/files/evo-media-document/20230321-apfit-biannual-report.pdf'+(f'#page={page}' if page else ''),'title':title,'company':' '.join(company[1].split()) if company else None,'contract_award_date_text':' '.join(dt[1].split()) if dt else None,'cohort_fiscal_year':2022,'report_date':'2023-03-15','selected_project_funding_usd':'10000000','money_semantics':'Report states ten FY2022 projects selected to receive $10M each from FY2022 APFIT procurement funding. Not a transaction-level obligation or payment; matching award may be counted in USAspending.','raw_page':page,'text':block,'evidence_excerpt':block[:1000]})
 d=pd.DataFrame(records);d.to_parquet(DATA/'normalized/apfit_fy2022_projects.parquet',index=False);d.to_json(DATA/'normalized/apfit_fy2022_projects.jsonl.gz',orient='records',lines=True,compression='gzip');d.head(4).to_json(ROOT/'samples/apfit_projects.jsonl',orient='records',lines=True);save_json(ROOT/'validation/apfit_project_profile.json',{'projects':len(d),'missing_company':int(d.company.isna().sum()),'missing_award_date_text':int(d.contract_award_date_text.isna().sum()),'expected_projects_in_report':10,'note':'Only FY2022 cohort in this report, not the current APFIT portfolio. Dates/companies can bridge to awards but no PIID in parsed cohort.'});print('APFIT projects',len(d),flush=True)
if __name__=='__main__':commons();apfit()
